#!/usr/bin/env python3
"""Embed Web/NigWeb.js into Sources/NigWebScript.h as an NSString.

Run from the project root after changing Web/NigWeb.js:
    python3 Web/embed.py
"""
import os
import sys

root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
src = os.path.join(root, "Web", "NigWeb.js")
dst = os.path.join(root, "Sources", "NigWebScript.h")

with open(src, encoding="utf-8") as f:
    js = f.read()
if '"' in js or "\\" in js:
    sys.exit("NigWeb.js must contain no double quotes and no backslashes")

lines = [
    "// Generated by Web/embed.py from Web/NigWeb.js. Edit that file, not this one.",
    "#pragma once",
    "#import <Foundation/Foundation.h>",
    "",
    "static NSString *const kNigWebEngine = @\"\"",
]
for line in js.rstrip("\n").split("\n"):
    lines.append('    "' + line + '\\n"')
lines[-1] += ";"
with open(dst, "w", encoding="utf-8") as f:
    f.write("\n".join(lines) + "\n")
print("wrote", os.path.relpath(dst, root), len(js), "bytes of script")
